(()=>{'use strict';const EN=document.documentElement.lang==='en',T=(v,e)=>EN?e:v,E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const layer={real:T('Ngoài đời','Real world'),verify:T('Xác nhận nhiều bên','Verified inputs'),chain:'Blockchain'};
const step=(title,actor,type,action,record)=>({title,actor,type,action,record});
const flows={
 acquire:{label:T('Sở hữu & phát hành','Ownership & issuance'),intro:T('Thử ba cách đưa một căn hiện hữu vào hệ thống. Token chỉ được mở phát hành sau các xác nhận bắt buộc.','Explore three ways to onboard an existing property. Issuance opens only after the required confirmations.'),steps:[
 step(T('Chủ sở hữu đồng ý','Owner consent'),T('Chủ nhà / chủ đầu tư','Homeowner / developer'),'real',T('Chọn bán một phần, bán toàn bộ hoặc bán cho Propertichain. Kiểm tra thẩm quyền và ghi nhận tỷ lệ được phép bán.','Select a partial sale, full sale or acquisition by Propertichain. Establish sale authority and the permitted share.'),T('Đề nghị và chấp thuận của chủ sở hữu','Owner request and consent')),
 step(T('Kiểm tra căn nhà','Verify the property'),T('Đơn vị thẩm định','Property reviewer'),'real',T('Kiểm tra hiện hữu, bàn giao, hồ sơ quyền, nghĩa vụ bảo đảm và hợp đồng thuê nếu có. Blockchain không tự kiểm tra căn nhà.','Check existence, handover, title, encumbrances and any lease. Blockchain cannot inspect the property itself.'),T('Kết quả thẩm định và tham chiếu hồ sơ','Review outcome and document reference')),
 step(T('Duyệt cấu trúc giao dịch','Approve the transaction structure'),T('Các bên có thẩm quyền','Authorized reviewers'),'verify',T('Xác nhận quyền token đại diện, định giá, điều kiện thanh toán và bảo lãnh nếu có. Không mặc định có ngân hàng hay Vingroup bảo lãnh.','Confirm token rights, valuation, settlement conditions and any guarantee. Bank or Vingroup guarantees are not assumed.'),T('Phiên bản điều kiện và xác nhận nhiều bên','Terms version and multi-party approval')),
 step(T('Ghi nhận điều kiện lên hệ thống','Record approved conditions'),T('Các bên xác nhận → hợp đồng','Attesters → contract'),'chain',T('Ghi mã căn, tỷ lệ bán và dấu xác thực hồ sơ đã duyệt; giữ quyền phát hành ở trạng thái khóa.','Record the property ID, permitted share and approved evidence fingerprints; keep issuance locked.'),T('Hồ sơ được duyệt; chưa phát hành','Approved record; issuance still locked')),
 step(T('Thanh toán theo phương án','Settle the selected route'),T('Bên mua / ngân hàng','Buyer / bank'),'real',T('Bán phần sở hữu: tiền trả cho người bán theo cấu trúc đã duyệt. Mua trước: Propertichain trả từ nguồn vốn của mình hoặc nguồn tài trợ đã cam kết. VND cần đối soát ngân hàng.','Fractional sale: proceeds go to the seller under the approved structure. Acquisition first: Propertichain pays using its capital or committed financing. VND needs bank reconciliation.'),T('Xác nhận thanh toán; không phải lợi nhuận nền tảng','Settlement confirmation; not platform profit')),
 step(T('Hoàn tất quyền đối với tài sản','Complete the rights arrangements'),T('Chủ sở hữu và bên xác minh','Owner and rights reviewer'),'verify',T('Xác nhận thủ tục và liên kết pháp lý phù hợp với phương án. Không cần Propertichain mua 100% trong mọi trường hợp.','Confirm the required formalities and legal linkage for the chosen route. Propertichain does not have to buy 100% in every route.'),T('Xác nhận quyền và điều kiện trước phát hành','Rights confirmation and issuance prerequisites')),
 step(T('Phát hành đúng phần sở hữu','Issue the authorized shares'),T('Hợp đồng phát hành','Issuance contract'),'chain',T('Kiểm tra đủ xác nhận, giới hạn nguồn cung và chống phát hành trùng trong hệ thống. Phân bổ cho chủ cũ và người mua theo tỷ lệ đã duyệt.','Check attestations, supply limits and duplicate issuance within the system. Allocate to the retained owner and buyers as approved.'),T('Tổng phần sở hữu 100%; tỷ lệ phân bổ được ghi lại','100% total ownership shares; allocation recorded'))]},
 rent:{label:T('Tiền thuê & phí','Rent & fees'),intro:T('Ví dụ riêng: cả kỳ thuê có 15 triệu đồng thực thu, 3 triệu chi phí và dự phòng đã duyệt, còn 12 triệu để phân phối. Phí dịch vụ nếu có phải nằm trong chi phí công bố.','Separate example: VND 15 million actually received, VND 3 million approved expenses and reserves, leaving VND 12 million to distribute. Any service fee must be included in disclosed expenses.'),steps:[
 step(T('Ký và quản lý hợp đồng thuê','Manage the lease'),T('Khách thuê / đơn vị quản lý','Tenant / operator'),'real',T('Ghi kỳ thuê, tiền phải trả và thời hạn. Có hợp đồng chưa có nghĩa đã nhận được tiền.','Record the rental period, amount due and term. A lease does not prove payment.'),T('Tham chiếu hợp đồng thuê','Lease reference')),
 step(T('Xác nhận tiền thực thu','Confirm actual receipts'),T('Ngân hàng / đối soát','Bank / reconciler'),'verify',T('Đối chiếu khoản 15 triệu thuộc đúng căn và đúng kỳ. Thiếu tiền thì không ghi như đã thu đủ.','Match VND 15 million to the correct property and period. Do not record unpaid amounts as collected.'),T('Thực thu đã đối chiếu, gắn mã căn và kỳ','Reconciled receipt linked to property and period')),
 step(T('Duyệt chi phí và dự phòng','Approve expenses and reserves'),T('Đơn vị quản lý / người duyệt','Operator / reviewer'),'verify',T('Duyệt 3 triệu chi phí và dự phòng, bao gồm phí dịch vụ đã thỏa thuận nếu có. Không trích tiền của căn khác.','Approve VND 3 million in expenses and reserves, including agreed service fees if any. Do not use another property’s funds.'),T('Quyết toán kỳ: 12 triệu có thể phân phối','Period statement: VND 12 million distributable')),
 step(T('Cấp đủ quỹ phân phối','Fund the distribution vault'),T('Đơn vị thanh toán → quỹ căn','Settlement operator → property vault'),'chain',T('Nếu phân phối onchain, phải nộp đủ tài sản thanh toán được chấp thuận vào quỹ. Xác nhận VND trong ngân hàng chưa tự tạo tiền trên blockchain.','For onchain distribution, approved settlement assets must actually fund the vault. A bank VND receipt does not create onchain funds.'),T('Số dư quỹ đã đủ cho kỳ thuê','Vault funded for the rental period')),
 step(T('Tính và nhận phần tiền thuê','Allocate and claim rent'),T('Hợp đồng / chủ token','Contract / token holders'),'chain',T('Tính theo tỷ lệ và thời gian giữ; mỗi người rút phần được nhận, không rút hai lần. Ví dụ giữ cả kỳ: chủ cũ 60% nhận 7,2 triệu; nhóm người mua 40% nhận 4,8 triệu.','Allocate by share and holding time; each holder claims only their entitlement once. Full-period example: retained 60% receives VND 7.2m; buyers holding 40% receive VND 4.8m.'),T('Quyền nhận và khoản đã rút; kỳ không bị trả trùng','Entitlements and claims; no duplicate payment'))]},
 incident:{label:T('Đóng băng & khôi phục','Freeze & recovery'),intro:T('Khóa chuyển nhượng, giữ chi trả và dừng thị trường là ba quyền riêng. Mô phỏng này chỉ khóa chuyển nhượng; tiền thuê đã tích lũy không bị xóa.','Transfer freezes, payment holds and market pauses are separate powers. This simulation freezes transfers only; accrued rent is not erased.'),steps:[
 step(T('Phát hiện và lập hồ sơ','Detect and document'),T('Giám sát / người báo sự cố','Monitor / incident reporter'),'real',T('Ghi nhận nghi vấn thao túng hoặc ví bị chiếm quyền. Cảnh báo chưa phải kết luận vi phạm.','Record suspected manipulation or wallet compromise. An alert is not a finding of wrongdoing.'),T('Mã sự cố và bằng chứng tham chiếu','Incident ID and evidence reference')),
 step(T('Tạm khóa đúng phạm vi','Freeze the affected scope'),T('Nhóm ứng cứu có quyền','Authorized response team'),'chain',T('Khóa phần token liên quan, không tự khóa mọi căn hoặc xóa tiền thuê. Chỉ can thiệp trong phạm vi hợp đồng cho phép.','Freeze the affected token amount without freezing every property or deleting rent. Intervention is limited to contract permissions.'),T('Phạm vi khóa, bên thực hiện và lý do','Freeze scope, actor and reason')),
 step(T('Điều tra và phê duyệt xử lý','Investigate and approve action'),T('Nhóm kiểm soát nhiều bên','Multi-party review group'),'verify',T('Kiểm tra bằng chứng, chủ sở hữu và thời hạn rà soát. Chuyển sang ví mới là quy trình riêng; demo này không tịch thu hoặc chuyển tài sản.','Review evidence, ownership and review deadlines. Moving rights to a new wallet is a separate process; this demo does not seize or transfer assets.'),T('Quyết định có trách nhiệm giải trình','Accountable review decision')),
 step(T('Mở khóa sau phê duyệt','Unfreeze after approval'),T('Các bên phê duyệt → hợp đồng','Approvers → contract'),'chain',T('Mở khóa theo quyết định hợp lệ và lưu dấu vết. Không thể dùng chức năng này để lấy lại tiền đã chuyển ra ngoài phạm vi hệ thống.','Unfreeze under valid approval and record the action. This cannot recover funds already moved outside the system’s control.'),T('Mở khóa; quyền nhận tiền được bảo toàn','Unfrozen; rental entitlements preserved'))]},
 valuation:{label:T('Định giá & chuyển nhượng','Valuation & transfers'),intro:T('Giá trị căn nhà và tiền thuê là hai dữ liệu độc lập. Việc cập nhật giá không làm tăng số tiền thuê được nhận.','Property value and rental income are independent. Updating the valuation does not increase rental receipts.'),steps:[
 step(T('Thu thập bằng chứng thị trường','Collect market evidence'),T('Đơn vị định giá','Valuation provider'),'real',T('Tách giá rao, giá giao dịch có bằng chứng và giá thẩm định; xét diện tích, tầng, hướng và nội thất. Không lấy giá token làm căn cứ duy nhất.','Separate asking prices, evidenced transactions and appraisals; consider area, floor, orientation and finishes. Token trades are not the sole evidence.'),T('Nguồn, thời điểm dữ liệu và phạm vi định giá','Sources, evidence date and valuation scope')),
 step(T('Duyệt giá nhiều bên','Approve the valuation'),T('Bên đề xuất / bên kiểm soát','Proposer / independent reviewer'),'verify',T('Kiểm tra biến động bất thường và độ tin cậy; thiếu dữ liệu thì giữ trạng thái chờ, không bịa một giá mới mỗi ngày.','Review unusual changes and evidence quality; insufficient data stays pending rather than generating a new daily price.'),T('Phiên bản định giá đã được duyệt','Approved valuation version')),
 step(T('Cập nhật giá tham chiếu','Publish the reference value'),T('Bên xác nhận → hợp đồng','Attesters → contract'),'chain',T('Ghi phiên bản, ngày hiệu lực và hạn dữ liệu. Khi dữ liệu hết hạn hoặc có sự cố, chặn giao dịch mới theo quy tắc.','Record version, effective date and expiry. Stale data or incidents block new trades under the policy.'),T('Lịch sử giá và điều kiện giao dịch','Valuation history and trading conditions')),
 step(T('Chuyển nhượng có kiểm soát','Settle a controlled transfer'),T('Người mua / người bán / hợp đồng','Buyer / seller / contract'),'chain',T('Kiểm tra giá, quyền chuyển, phần token đang khóa và tài sản thanh toán. Chỉ hoàn tất khi đủ điều kiện; không có người mua thì không cam kết thanh khoản. Hoán đổi token căn khác cần định giá và chấp thuận của cả hai bên.','Check price, transfer eligibility, frozen balances and settlement assets. Settle only when conditions are met; no buyer means no guaranteed liquidity. Property-token swaps require valuations and both parties’ consent.'),T('Chuyển phần sở hữu; giữ lại quyền tiền thuê cũ','Ownership transfer; prior rent entitlement retained'))]}}
let selected='acquire',index=0,ledger=[],blocked='',route='partial';const host=document.getElementById('workflow-root');
const rows=[
[T('Định danh căn','Property identity'),T('Mã căn, liên kết token, dấu xác thực hồ sơ','Property ID, token linkage, document fingerprint'),T('Kiểm tra căn thực và quyền đối với căn','Verify physical property and rights')],
[T('Mua / bán phần sở hữu','Purchase / fractional sale'),T('Tỷ lệ, điều kiện, phê duyệt và phân bổ','Shares, conditions, approvals and allocations'),T('Thẩm quyền bán, đồng ý và thủ tục chuyển quyền','Sale authority, consent and rights formalities')],
[T('Thanh toán & bảo lãnh','Payment & guarantees'),T('Ghi nhận xác nhận; chuyển tài sản onchain có điều kiện','Record confirmations; conditional onchain settlement'),T('Ngân hàng đối soát VND và thực hiện cam kết bảo lãnh cụ thể','Bank reconciles VND and performs specified guarantees')],
[T('Định giá','Valuation'),T('Lưu phiên bản, hạn dữ liệu và quy tắc giao dịch','Store versions, expiry and trade rules'),T('Bằng chứng thị trường, thẩm định và người phê duyệt','Market evidence, appraisal and approvers')],
[T('Thuê & phân phối','Rent & distribution'),T('Quỹ từng căn, quyền nhận và chặn trả trùng','Per-property vaults, entitlements and duplicate prevention'),T('Khách thuê, thực thu, chi phí và chứng từ','Tenant, actual receipts, costs and records')],
[T('Biểu quyết & phí dịch vụ','Voting & service fees'),T('Quyền biểu quyết, ngưỡng duyệt và phí đã thỏa thuận','Voting rights, approval thresholds and agreed fees'),T('Điều lệ, hợp đồng dịch vụ và thực hiện công việc','Governing terms, service agreements and delivery')],
[T('Sự cố & tranh chấp','Incidents & disputes'),T('Khóa, tạm dừng, mở khóa theo quyền; nhật ký','Authorized freezes, pauses, unfreezes and event logs'),T('Điều tra, xác minh và giải quyết tranh chấp','Investigation, identity checks and dispute resolution')]
];
host.innerHTML=`<section id="workflows"><div class="eyebrow">${T('Hiểu cách hệ thống vận hành','Understand how it works')}</div><h2>${T('Việc thật bên ngoài. Quy tắc rõ trên blockchain.','Real-world actions. Clear onchain rules.')}</h2><p class="wf-intro">${T('Hợp đồng thông minh thực thi điều kiện và ghi lại dấu vết. Con người, doanh nghiệp và ngân hàng vẫn phải thực hiện và chịu trách nhiệm về công việc ngoài đời.','Smart contracts enforce conditions and record events. People, businesses and banks still perform and take responsibility for real-world work.')}</p><div class="wf-layers"><div><span>01</span><h3>${layer.real}</h3><p>${T('Căn nhà, hợp đồng, tiền ngân hàng và vận hành cho thuê.','Property, agreements, bank money and rental operations.')}</p></div><div><span>02</span><h3>${layer.verify}</h3><p>${T('Các bên có thẩm quyền kiểm tra, ký xác nhận và cung cấp bằng chứng.','Authorized parties review, attest and provide supporting evidence.')}</p></div><div><span>03</span><h3>${layer.chain}</h3><p>${T('Kiểm tra điều kiện, ghi nhận phần sở hữu và phân phối khoản đã được cấp đủ.','Check conditions, record ownership shares and distribute funded amounts.')}</p></div></div><div class="wf-note">${T('Đây là quy trình thiết kế và mô phỏng. Chưa có hợp đồng onchain, giao dịch tài sản hoặc bảo lãnh ngân hàng thật. Ghi dữ liệu lên blockchain không tự chứng minh dữ liệu đúng hoặc tạo ra quyền sở hữu pháp lý.','This is a proposed workflow simulation. No onchain contracts, asset transactions or actual bank guarantees are in place. Recording data onchain does not prove its truth or create legal title.')}</div><div class="wf-tabs" role="group" aria-label="${T('Chọn quy trình','Choose a workflow')}">${Object.entries(flows).map(([k,f])=>`<button data-flow="${k}" aria-pressed="${k===selected}">${f.label}</button>`).join('')}</div><p id="wf-description"></p><div id="wf-route-wrap"><label for="wf-route">${T('Phương án sở hữu giả lập','Simulated ownership route')}</label><select id="wf-route"><option value="partial">${T('Chủ nhà bán 40%, giữ 60%','Owner sells 40%, retains 60%')}</option><option value="full">${T('Chủ nhà bán toàn bộ qua cấu trúc token hóa','Owner sells all through tokenization structure')}</option><option value="buyout">${T('Propertichain mua trước rồi phân phối','Propertichain acquires first, then distributes')}</option></select><p id="wf-route-note" class="muted"></p></div><div class="wf-progress"><span id="wf-progress-label"></span><progress id="wf-progress" value="0" max="7"></progress></div><div class="wf-player"><ol id="wf-step-list" aria-label="${T('Các bước của quy trình','Workflow steps')}"></ol><div class="wf-detail"><span id="wf-step-type" class="wf-badge"></span><h3 id="wf-step-title"></h3><p id="wf-step-actor" class="muted"></p><p id="wf-step-action"></p><div class="wf-evidence"><small>${T('DẤU VẾT CẦN LƯU','RECORD TO KEEP')}</small><p id="wf-step-record"></p></div><div class="wf-controls"><button id="wf-next" class="cta"></button><button id="wf-reset" class="cta outline">${T('Làm lại','Reset')}</button></div><button id="wf-early" class="wf-early"></button><p id="wf-feedback" role="status"></p></div></div><div class="wf-ledger"><h3>${T('Nhật ký mô phỏng','Simulated activity log')}</h3><p class="muted">${T('Chỉ lưu trong trang đang mở; không phải giao dịch blockchain, chữ ký thật hoặc chứng từ có giá trị pháp lý.','Stored only in the current page; not blockchain transactions, actual signatures or legally effective evidence.')}</p><ol id="wf-log" aria-live="polite"></ol></div><details class="wf-matrix"><summary>${T('Xem ranh giới tự động hóa của toàn bộ quy trình','See automation boundaries across the lifecycle')}</summary><div class="wf-table-wrap"><table><thead><tr><th>${T('Quy trình','Process')}</th><th>${T('Hợp đồng / bản ghi blockchain','Contract / blockchain record')}</th><th>${T('Phần cần ngoài đời','Offchain responsibility')}</th></tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(c=>'<td>'+E(c)+'</td>').join('')+'</tr>').join('')}</tbody></table></div></details><div class="wf-private"><h3>${T('Giấy tờ riêng tư được lưu ở đâu?','Where do private documents go?')}</h3><p>${T('Giấy tờ cá nhân, hợp đồng thuê và hồ sơ ngân hàng được lưu ngoài blockchain, có quyền truy cập. Blockchain dự kiến lưu mã hồ sơ, dấu xác thực, phiên bản, bên xác nhận và thời điểm để đối chiếu; không công khai toàn bộ tài liệu.','Personal documents, leases and bank records remain offchain under access controls. The proposed onchain record stores references, fingerprints, versions, attesters and timestamps for comparison, not full public documents.')}</p></div></section>`;
const $=id=>document.getElementById(id),routes={partial:T('Chủ nhà giữ 60% và hưởng phần tiền thuê tương ứng; người mua nhận 40%. Đây chỉ là tỷ lệ minh họa.','Owner retains 60% with corresponding rental rights; buyers receive 40%. These percentages are illustrative.'),full:T('Người bán thoái toàn bộ quyền được chuyển giao; Propertichain tổ chức giao dịch theo cấu trúc đã duyệt.','Seller exits all transferred rights; Propertichain organizes the transaction under the approved structure.'),buyout:T('Propertichain cần nguồn tiền mua trước. Tiền bán phần sở hữu sau đó không đồng nghĩa toàn bộ là lợi nhuận.','Propertichain needs acquisition funding first. Subsequent share-sale proceeds are not all profit.')};
function render(){const f=flows[selected],done=index===f.steps.length,s=f.steps[Math.min(index,f.steps.length-1)];$('wf-description').textContent=f.intro;$('wf-route-wrap').hidden=selected!=='acquire';$('wf-route-note').textContent=routes[route];$('wf-progress').max=f.steps.length;$('wf-progress').value=index;$('wf-progress-label').textContent=T('Đã hoàn tất ','Completed ')+index+'/'+f.steps.length+T(' bước giả lập',' simulated steps');document.querySelectorAll('[data-flow]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.flow===selected)));$('wf-step-list').innerHTML=f.steps.map((x,i)=>'<li class="'+(i<index?'done':i===index?'current':'')+'"><span>'+(i<index?'✓':i+1)+'</span><div>'+E(x.title)+'<small>'+E(layer[x.type])+'</small></div></li>').join('');$('wf-step-type').textContent=done?T('Hoàn tất mô phỏng','Simulation complete'):layer[s.type];$('wf-step-title').textContent=done?T('Quy trình đã đi qua đủ bước.','Every step has been completed.'):s.title;$('wf-step-actor').textContent=done?'':T('Bên thực hiện: ','Responsible party: ')+s.actor;$('wf-step-action').textContent=done?T('Các kết quả dưới đây chỉ minh họa cách phối hợp ngoài đời và blockchain, không xác nhận một giao dịch thật.','These results illustrate offchain and onchain coordination, not an actual completed transaction.'):s.action;$('wf-step-record').textContent=done?(selected==='acquire'?routes[route]:selected==='rent'?T('12 triệu giả lập: 7,2 triệu cho 60% và 4,8 triệu cho 40%, nếu nắm cả kỳ.','VND 12m simulated: 7.2m for 60% and 4.8m for 40%, if held for the full period.'):T('Nhật ký bên dưới giữ lại toàn bộ bước vừa thực hiện.','The log below preserves the completed steps.')):s.record;$('wf-next').disabled=done;$('wf-next').textContent=done?T('Đã hoàn tất','Completed'):T('Mô phỏng bước này →','Simulate this step →');$('wf-early').hidden=!['acquire','rent'].includes(selected)||done;$('wf-early').textContent=selected==='acquire'?T('Thử phát hành token ngay','Try issuing tokens now'):T('Thử phân phối tiền thuê ngay','Try distributing rent now');$('wf-feedback').textContent=blocked;$('wf-log').innerHTML=ledger.length?ledger.map((x,i)=>'<li><span>'+String(i+1).padStart(2,'0')+'</span><div><b>'+E(x.title)+'</b><small>'+E(x.type)+' · '+E(x.record)+'</small></div></li>').join(''):'<li class="muted">'+T('Chưa có bước nào được xác nhận giả lập.','No simulated steps confirmed yet.')+'</li>';}
function reset(){index=0;ledger=[];blocked='';render()}
document.querySelectorAll('[data-flow]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.flow;reset()}));$('wf-route').addEventListener('change',e=>{route=e.target.value;reset()});$('wf-reset').addEventListener('click',reset);$('wf-next').addEventListener('click',()=>{const f=flows[selected];if(index>=f.steps.length)return;const s=f.steps[index];ledger.push({title:s.title,type:layer[s.type],record:s.record});index++;blocked='';render()});$('wf-early').addEventListener('click',()=>{const f=flows[selected];if(index<f.steps.length-1){blocked=selected==='acquire'?T('Bị chặn trong mô phỏng: cần hoàn tất các xác nhận, thanh toán và quyền đối với tài sản trước khi phát hành.','Blocked in simulation: required approvals, settlement and rights arrangements must be completed before issuance.'):T('Bị chặn trong mô phỏng: cần xác nhận thực thu, chi phí và cấp đủ quỹ trước khi phân phối.','Blocked in simulation: verify actual receipts and expenses, then fund the vault before distribution.');render()}else{blocked=T('Đã đủ bước chuẩn bị giả lập. Bấm mô phỏng bước cuối để xem kết quả; không có giao dịch thật.','Simulated prerequisites are complete. Use the final step to see the result; no real transaction occurs.');render()}});render();
})();
